<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {api} from './api'
import SitePostSettings from './SitePostSettings.vue'
const props=defineProps({token:String,language:String,initialView:{type:String,default:'overview'}})
const emit=defineEmits(['dirty'])
const tr=(ru,uz,en)=>({ru,uz,en}[props.language]||ru)
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tashkent',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const from=ref(today()),to=ref(today()),kind=ref('all'),postNo=ref(''),view=ref(props.initialView),data=ref(null),busy=ref(false),error=ref(''),selected=ref(null),dirty=ref(false)
const n=v=>Number(v||0).toLocaleString(props.language==='ru'?'ru-RU':'en-US')
const stamp=v=>v?new Date(v).toLocaleString(props.language==='uz'?'uz-UZ':props.language==='en'?'en-GB':'ru-RU',{timeZone:'Asia/Tashkent'}):'—'
const device=k=>k==='dry_fog'?tr('Арома','Aroma','Aroma'):k==='wash'?tr('Мойка','Yuvish','Wash'):tr('Тип неизвестен','Turi noma’lum','Unknown type')
const mode=k=>({water:'SUV',foam:'KO‘PIK',wax:'MUM',chem:'KIMYO',osmos:'OSMOS',nano:'NANO',air:'HAVO',vacuum:'CHANGYUTGICH',aroma_1:'SHEIKH SULTAN',aroma_2:'BLACK ICE',aroma_3:'NARCOTIC',aroma_4:'INVICTUS CREED',aroma_5:'ANTI-TOBACCO',blackening:'SHINA QORAYTIRISH',tank_air:'SHINANI DAMLASH',pause:'PAUZA'}[k]||k)
function status(p){if(p.status!=='online')return tr('Нет связи','Aloqa yo‘q','Offline');if(!p.state.lastIoOk)return tr('Ошибка оборудования','Uskuna xatosi','Hardware fault');if(p.state.activeMode)return mode(p.state.activeMode);if(p.state.activeSessionId||p.state.creditSum)return tr('Сеанс открыт','Seans ochiq','Session open');return tr('Свободен','Bo‘sh','Available')}
async function load(){if(busy.value)return;busy.value=true;error.value='';try{data.value=await api('/api/owner/site/overview?'+new URLSearchParams({date_from:from.value,date_to:to.value,device_type:kind.value,...(postNo.value?{post_no:postNo.value}:{})}),{token:props.token,signal:AbortSignal.timeout(20000)})}catch(e){error.value=e.message}finally{busy.value=false}}
const metrics=computed(()=>!data.value?[]:[
 [tr('Поступления','Tushumlar','Receipts'),data.value.summary.receipts_sum,tr('Наличные + Click. Переносы картой исключены.','Naqd + Click. Karta o‘tkazmalari kiritilmaydi.','Cash + Click. Card transfers excluded.')],
 [tr('Оказано услуг','Ko‘rsatilgan xizmatlar','Services delivered'),data.value.summary.service_sum,tr('Деньги и бонусы; VIP отдельно','Pul va bonuslar; VIP alohida','Money and bonuses; VIP separate')],
 [tr('Наличные','Naqd','Cash'),data.value.summary.cash_sum,''],['Click',data.value.summary.click_sum,'']])
function settings(post){if(dirty.value)return;selected.value=post;view.value='settings'}
function dirtyChanged(v){dirty.value=v;emit('dirty',v)}
let timer;onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden&&view.value!=='settings')load()},30000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="site-owner">
<div class="heading site-heading"><div><p class="site-eyebrow">LABRIX · {{tr('Управление объектом','Obyekt boshqaruvi','Site management')}}</p><h1>{{initialView==='reports'?tr('Отчёты','Hisobotlar','Reports'):tr('Вся мойка','Barcha postlar','Site overview')}}</h1><p>{{tr('Мойка и арома · локальная сеть','Yuvish va aroma · mahalliy tarmoq','Wash and aroma · local network')}}</p></div><span v-if="data" class="site-sync">{{tr('На связи','Ulangan','Online')}} {{data.online_posts}} / {{data.posts.length}}<small>{{stamp(data.checked_at)}}</small></span></div>
<div class="site-tabs" role="tablist"><button v-for="[key,ru,uz,en] in [['overview','Обзор','Umumiy','Overview'],['reports','Подробный отчёт','Batafsil hisobot','Detailed report']]" :key="key" class="quiet" :class="{selected:view===key}" :disabled="dirty" @click="view=key">{{tr(ru,uz,en)}}</button></div>
<form v-if="view!=='settings'" class="card site-filters" @submit.prevent="load"><label>{{tr('С','Dan','From')}}<input type="date" v-model="from" :max="to" required/></label><label>{{tr('По','Gacha','To')}}<input type="date" v-model="to" :min="from" required/></label><label>{{tr('Оборудование','Qurilma','Device')}}<select v-model="kind"><option value="all">{{tr('Все','Barchasi','All')}}</option><option value="wash">{{tr('Мойка','Yuvish','Wash')}}</option><option value="dry_fog">{{tr('Арома','Aroma','Aroma')}}</option></select></label><label>{{tr('Пост','Post','Station')}}<select v-model="postNo"><option value="">{{tr('Все посты','Barcha postlar','All stations')}}</option><option v-for="p in data?.inventory||data?.posts||[]" :key="p.post_no" :value="String(p.post_no)">{{p.post_no}} · {{device(p.device_type)}}</option></select></label><button class="primary" :disabled="busy">{{busy?tr('Загрузка…','Yuklanmoqda…','Loading…'):tr('Обновить','Yangilash','Refresh')}}</button></form>
<div v-if="error" class="message error" role="alert">{{error}}<p v-if="data">{{tr('Ниже показаны предыдущие данные. Последнее успешное обновление:','Quyida oldingi ma’lumotlar. Oxirgi muvaffaqiyatli yangilanish:','Previous data is shown below. Last successful update:')}} {{stamp(data.checked_at)}}</p></div>
<template v-if="data">
<p v-if="!data.complete" class="message error" role="status">{{tr('Данные неполные. В итог включены только посты на связи; недоступный пост не считается нулевым.','Ma’lumot to‘liq emas. Jami faqat ulangan postlarni o‘z ichiga oladi; ulanmagan post nol deb hisoblanmaydi.','Incomplete data. Totals include responding stations only; offline stations are not treated as zero.')}}</p>
<p v-if="!data.manage_allowed" class="message">{{tr('Просмотр доступен. Настройки всех постов меняются на текущем главном: пост','Ko‘rish mumkin. Barcha postlar sozlamalari asosiy postda o‘zgartiriladi:','Read access available. Change settings on the current primary: station')}} {{data.primary_post}}. <a v-if="data.primary_url" :href="data.primary_url+'/owner/site'">{{tr('Открыть главный пост','Asosiy postni ochish','Open primary station')}}</a></p>
<template v-if="view!=='settings'">
<div class="site-metrics"><section v-for="(m,i) in metrics" :key="m[0]" class="card site-metric" :class="{principal:i===0}"><p>{{m[0]}}</p><strong>{{data.online_posts?n(m[1]):'—'}} <small>so‘m</small></strong><span>{{m[2]}}</span></section></div>
<p v-if="!data.posts.length" class="message">{{tr('Нет постов по выбранным фильтрам.','Tanlangan filtrlar bo‘yicha post yo‘q.','No stations match these filters.')}}</p><div v-if="view==='overview'" class="site-post-grid"><article v-for="p in data.posts" :key="p.post_no" class="card site-post" :class="{unavailable:p.status!=='online'}"><header><div><small>{{device(p.device_type)}}</small><h2>{{p.name||tr('Пост','Post','Station')+' '+String(p.post_no).padStart(2,'0')}}</h2></div><span class="status-pill" :class="{positive:p.status==='online'&&p.state?.lastIoOk}">{{status(p)}}</span></header><dl><div><dt>{{tr('Поступления','Tushumlar','Receipts')}}</dt><dd>{{p.report?n(p.report.summary.receipts_sum)+' so‘m':'—'}}</dd></div><div><dt>{{tr('Оказано услуг','Ko‘rsatilgan xizmatlar','Services')}}</dt><dd>{{p.report?n(p.report.summary.service_sum)+' so‘m':'—'}}</dd></div><div><dt>{{tr('Последняя связь','Oxirgi aloqa','Last seen')}}</dt><dd>{{stamp(p.last_seen_at)}}</dd></div></dl><footer><span v-if="p.status==='online'">Click: {{p.click==='configured'?tr('Настроен','Sozlangan','Configured'):p.click==='disabled'?tr('Выключен','O‘chirilgan','Disabled'):p.click==='offline'?tr('Нет связи с сервером','Server bilan aloqa yo‘q','Server offline'):tr('Не готов','Tayyor emas','Not ready')}}</span><button class="quiet" :disabled="p.status!=='online'" @click="settings(p.post_no)">{{tr('Настройки','Sozlamalar','Settings')}}</button></footer></article></div>
<template v-else><section class="card site-detail"><h2>{{tr('Состав использования','Foydalanish tarkibi','Usage breakdown')}}</h2><dl class="site-breakdown"><div v-for="[key,ru,uz,en] in [['money_spent_sum','Израсходовано денег','Sarflangan pul','Money spent'],['bonus_granted_sum','Начислено бонусов','Hisoblangan bonuslar','Bonuses awarded'],['bonus_spent_sum','Израсходовано бонусов','Sarflangan bonuslar','Bonuses spent'],['vip_virtual_spent_sum','VIP: виртуальный расход','VIP: virtual sarf','VIP: virtual usage'],['customer_saved_sum','Перенесено на карты','Kartalarga o‘tkazildi','Saved to cards'],['customer_used_sum','Получено с карт','Kartalardan olindi','Loaded from cards'],['test_credit_sum','Тестовые начисления (не выручка)','Sinov mablag‘lari (tushum emas)','Test credits (not receipts)']]" :key="key"><dt>{{tr(ru,uz,en)}}</dt><dd>{{n(data.summary[key])}} so‘m</dd></div></dl><p>{{tr('Переносы картой и VIP не являются новыми поступлениями. Услуги включают списания бонусов; расход денег показан отдельно.','Karta o‘tkazmalari va VIP yangi tushum emas. Xizmatlar bonus sarfini ham o‘z ichiga oladi; pul sarfi alohida ko‘rsatilgan.','Card transfers and VIP are not new receipts. Services include bonus consumption; money spent is shown separately.')}}</p></section>
<section class="card site-detail"><h2>{{tr('Поступления по дням','Kunlik tushumlar','Daily receipts')}}</h2><div class="table-wrap"><table><thead><tr><th>{{tr('Дата','Sana','Date')}}</th><th>{{tr('Наличные','Naqd','Cash')}}</th><th>Click</th><th>{{tr('Итого','Jami','Total')}}</th></tr></thead><tbody><tr v-for="r in data.timeline" :key="r.day"><td>{{r.day}}</td><td>{{n(r.cash_sum)}}</td><td>{{n(r.click_sum)}}</td><td>{{n(r.cash_sum+r.click_sum)}}</td></tr></tbody></table></div><p v-if="!data.timeline.length" class="empty">{{tr('Поступлений нет','Tushum yo‘q','No receipts')}}</p></section>
<section class="card site-detail"><h2>{{tr('Услуги','Xizmatlar','Services')}}</h2><div class="table-wrap"><table><thead><tr><th>{{tr('Услуга','Xizmat','Service')}}</th><th>{{tr('Минуты','Daqiqa','Minutes')}}</th><th>{{tr('Деньги','Pul','Money')}}</th><th>{{tr('Бонусы','Bonuslar','Bonuses')}}</th><th>VIP</th></tr></thead><tbody><tr v-for="r in data.modes" :key="r.mode"><th>{{mode(r.mode)}}</th><td>{{n(Math.round(r.duration_ms/6000)/10)}}</td><td>{{n(r.service_sum-r.bonus_spent_sum)}}</td><td>{{n(r.bonus_spent_sum)}}</td><td>{{n(r.vip_virtual_spent_sum)}}</td></tr></tbody></table></div></section></template>
<p class="site-note">{{tr('Обновление каждые 30 секунд. Время — Ташкент. Поступления — по времени платежа; услуги — по началу записанного интервала работы.','Har 30 soniyada yangilanadi. Vaqt — Toshkent. Tushumlar to‘lov vaqtiga, xizmatlar qayd etilgan ish oralig‘i boshlanishiga tegishli.','Refreshes every 30 seconds. Tashkent time. Receipts use payment time; services use the start of the recorded usage segment.')}}</p>
</template>
<template v-else><button class="quiet" :disabled="dirty" @click="view='overview'">← {{tr('К обзору','Umumiy ko‘rinishga','Back to overview')}}</button><SitePostSettings :post="selected" :token="token" :language="language" :manage-allowed="data.manage_allowed" @dirty="dirtyChanged"/></template>
</template></section></template>
<style scoped>
.site-heading{display:flex;justify-content:space-between;gap:20px;align-items:center}.site-eyebrow{font-size:12px;letter-spacing:.12em;text-transform:uppercase}.site-sync{text-align:right;font-weight:600}.site-sync small{display:block;color:var(--muted);font-size:12px;margin-top:8px}.site-tabs{display:flex;gap:8px;margin-bottom:16px}.site-tabs .selected{background:var(--selected);color:var(--accent)}.site-filters{display:grid;grid-template-columns:1fr 1fr 1fr 1fr auto;gap:16px;padding:20px;margin-bottom:20px;align-items:end}.site-filters label{min-width:0;display:flex;flex-direction:column;gap:8px}.site-filters input,.site-filters select{width:100%;min-width:0}.site-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:24px}.site-metric{padding:24px}.site-metric p{margin:0 0 16px;color:var(--muted)}.site-metric strong{display:block;font-size:clamp(26px,2.5vw,40px);font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.site-metric strong small{font-size:13px;font-weight:400}.site-metric span{display:block;font-size:12px;color:var(--muted);margin-top:12px;line-height:1.5}.principal{border-top:3px solid var(--accent)}.site-post-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.site-post{padding:24px}.site-post header,.site-post footer{display:flex;justify-content:space-between;gap:16px;align-items:center}.site-post h2{margin:6px 0;font-size:23px}.site-post small,.site-post footer>span{color:var(--muted);font-size:13px}.site-post dl{margin:20px 0}.site-post dl>div,.site-breakdown>div{display:flex;justify-content:space-between;gap:24px;padding:12px 0;border-bottom:1px solid var(--border)}.site-post dt{color:var(--muted)}.site-post dd,.site-breakdown dd{margin:0;text-align:right;font-variant-numeric:tabular-nums}.site-post dl>div:last-child{font-size:12px}.unavailable{border-style:dashed}.site-detail{margin:20px 0;padding:24px}.site-detail h2{font-size:21px;margin:0 0 20px}.site-detail p,.site-note{font-size:13px;color:var(--muted);line-height:1.6}.site-note{margin:24px 0}.site-breakdown{margin:0}.site-detail th,.site-detail td{white-space:nowrap}@media(max-width:1100px){.site-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.site-filters{grid-template-columns:1fr 1fr}.site-post-grid{grid-template-columns:1fr}}@media(max-width:600px){.site-heading{align-items:start}.site-heading h1{font-size:28px}.site-sync{font-size:12px}.site-sync small{max-width:125px}.site-filters{padding:16px;gap:12px}.site-metric{padding:16px}.site-post,.site-detail{padding:16px}.site-post header{align-items:start}.site-post h2{font-size:20px}.site-tabs button{padding:12px;font-size:14px}.site-breakdown>div{gap:12px}.site-breakdown dt{max-width:65%}}
</style>
